tinymce.PluginManager.add("magix_bs_grid",(function(editor,url){editor.ui.registry.addIcon("bs-columns",'<svg width="24" height="24" viewBox="0 0 24 24" focusable="false"><path d="M3 4h5v16H3V4zm7 0h4v16h-4V4zm6 0h5v16h-5V4z" fill="currentColor"/></svg>');editor.ui.registry.addButton("bs_grid",{icon:"bs-columns",tooltip:"Insérer des colonnes (Bootstrap 5)",onAction:function(){editor.windowManager.open({title:"Créer une structure en colonnes",body:{type:"panel",items:[{type:"selectbox",name:"gridType",label:"Format de la grille",items:[{text:"2 Colonnes (50% - 50%)",value:"2"},{text:"3 Colonnes (33% - 33% - 33%)",value:"3"},{text:"4 Colonnes (25% - 25% - 25% - 25%)",value:"4"}]},{type:"checkbox",name:"addGap",label:"Ajouter un espacement entre les colonnes (gap-4)"}]},buttons:[{type:"cancel",text:"Annuler"},{type:"submit",text:"Insérer",primary:true}],onSubmit:function(api){var data=api.getData();var cols=parseInt(data.gridType);var gapClass=data.addGap?" g-4":"";var colClass="col-12 ";if(cols===2)colClass+="col-md-6";if(cols===3)colClass+="col-md-4";if(cols===4)colClass+="col-md-6 col-lg-3";var html='<div class="row'+gapClass+' my-4">';for(var i=0;i<cols;i++){html+='<div class="'+colClass+'"><p>Contenu de la colonne '+(i+1)+"</p></div>"}html+="</div><p>&nbsp;</p>";editor.insertContent(html);api.close()}})}});return{getMetadata:function(){return{name:"Magix Bootstrap Grid",url:"https://www.magix-cms.com"}}}}));